component XXXFixedWidthOverflowRungB
export Executable

overflows(f: () -> Any): Boolean =
  try
    ignore(f())
    false
  catch e
    IntegerOverflow => true
  end

run(): () = do
    println("REACHED")
    one: ZZ32 = 1
    mOne: ZZ32 = -1
    k46341: ZZ32 = 46341
    zMax: ZZ32 = 7FFFFFFF_16
    zMin: ZZ32 = -zMax - 1
    lOne: ZZ64 = widen(one)
    lMOne: ZZ64 = widen(mOne)
    s00: ZZ64 = 3037000500
    lMax: ZZ64 = 7FFFFFFFFFFFFFFF_16
    lMin: ZZ64 = -lMax - 1
    assert(overflows(fn () => zMax + one), "row 379: ZZ32 MAX + 1 throws IntegerOverflow; Specification/basic/operators/opr-overview.tex:195-196")
    assert(overflows(fn () => zMin - one), "row 379: ZZ32 MIN - 1; opr-overview.tex:195-196")
    assert(overflows(fn () => -zMin), "row 379: ZZ32 -MIN; opr-overview.tex:154-155 with basic-integers.tex:380")
    assert(overflows(fn () => |zMin|), "row 379: ZZ32 |MIN|; opr-overview.tex:154-155 with basic-integers.tex:608-609")
    assert(overflows(fn () => zMin DIV mOne), "row 379: ZZ32 MIN DIV -1; opr-overview.tex:154-155")
    assert(overflows(fn () => k46341 DOT k46341), "row 379: ZZ32 46341 DOT 46341; opr-overview.tex:154-155")
    assert(overflows(fn () => lMax + lOne), "row 379: ZZ64 MAX + 1; opr-overview.tex:195-196")
    assert(overflows(fn () => lMin - lOne), "row 379: ZZ64 MIN - 1; opr-overview.tex:195-196")
    assert(overflows(fn () => -lMin), "row 379: ZZ64 -MIN; opr-overview.tex:154-155 with basic-integers.tex:380")
    assert(overflows(fn () => |lMin|), "row 379: ZZ64 |MIN|; opr-overview.tex:154-155 with basic-integers.tex:608-609")
    assert(overflows(fn () => lMin DIV lMOne), "row 379: ZZ64 MIN DIV -1; opr-overview.tex:154-155")
    assert(overflows(fn () => s00 DOT s00), "row 379: ZZ64 3037000500 DOT 3037000500; opr-overview.tex:154-155")
    println("PASS")
  end

end

== ProjectFortress/tests/WrapOperatorsRungD.fss:1-89

component WrapOperatorsRungD
export Executable

(*) explorations/compile-ladder/rung-wrap-operators/REPORT.md

shown(v: Any): String =
  typecase v of
    ZZ32 => v.asString || " : ZZ32"
    NN32 => v.asString || " : NN32"
    ZZ64 => v.asString || " : ZZ64"
    NN64 => v.asString || " : NN64"
    ZZ => v.asString || " : ZZ"
    else => v.asString || " : other"
  end

run() = do
    oneI: ZZ32 = 1
    twoI: ZZ32 = 2
    minusOneI: ZZ32 = -1
    minI: ZZ32 = -2147483647 - 1
    maxI: ZZ32 = 2147483647
    bigI: ZZ32 = 65536

    assert(shown(maxI DOTPLUS oneI), "-2147483648 : ZZ32", "opr-overview.tex:205-209: ZZ32 MAX DOTPLUS 1 wraps")
    assert(shown(minI DOTMINUS oneI), "2147483647 : ZZ32", "opr-overview.tex:205-209: ZZ32 MIN DOTMINUS 1 wraps")
    assert(shown(DOTMINUS minI), "-2147483648 : ZZ32", "opr-overview.tex:205-209: ZZ32 DOTMINUS MIN wraps")
    assert(shown(DOTMINUS maxI), "-2147483647 : ZZ32", "opr-overview.tex:205-209: ZZ32 DOTMINUS MAX")
    assert(shown(maxI DOTTIMES twoI), "-2 : ZZ32", "opr-overview.tex:172-176: ZZ32 MAX DOTTIMES 2 wraps")
    assert(shown(minI DOTTIMES minusOneI), "-2147483648 : ZZ32", "opr-overview.tex:172-176: ZZ32 MIN DOTTIMES -1 wraps")
    assert(shown(bigI DOTTIMES bigI), "0 : ZZ32", "opr-overview.tex:172-176: ZZ32 2^16 DOTTIMES 2^16 wraps")
    assert(shown((maxI DOTMINUS oneI) DOTPLUS twoI), "-2147483648 : ZZ32", "opr-overview.tex:205-209: ZZ32 DOTMINUS then DOTPLUS")

    oneL: ZZ64 = widen(1)
    twoL: ZZ64 = widen(2)
    minusOneL: ZZ64 = widen(-1)
    minL: ZZ64 = oneL LSHIFT 63
    maxL: ZZ64 = BITNOT minL
    bigL: ZZ64 = oneL LSHIFT 32

    assert(shown(maxL DOTPLUS oneL), "-9223372036854775808 : ZZ64", "opr-overview.tex:205-209: ZZ64 MAX DOTPLUS 1 wraps")
    assert(shown(minL DOTMINUS oneL), "9223372036854775807 : ZZ64", "opr-overview.tex:205-209: ZZ64 MIN DOTMINUS 1 wraps")
    assert(shown(DOTMINUS minL), "-9223372036854775808 : ZZ64", "opr-overview.tex:205-209: ZZ64 DOTMINUS MIN wraps")
    assert(shown(DOTMINUS maxL), "-9223372036854775807 : ZZ64", "opr-overview.tex:205-209: ZZ64 DOTMINUS MAX")
    assert(shown(maxL DOTTIMES twoL), "-2 : ZZ64", "opr-overview.tex:172-176: ZZ64 MAX DOTTIMES 2 wraps")
    assert(shown(minL DOTTIMES minusOneL), "-9223372036854775808 : ZZ64", "opr-overview.tex:172-176: ZZ64 MIN DOTTIMES -1 wraps")
    assert(shown(maxL DOTTIMES maxL), "1 : ZZ64", "opr-overview.tex:172-176: ZZ64 MAX DOTTIMES MAX wraps")
    assert(shown(bigL DOTTIMES bigL), "0 : ZZ64", "opr-overview.tex:172-176: ZZ64 2^32 DOTTIMES 2^32 wraps")

    zeroU: NN32 = unsigned(0)
    oneU: NN32 = unsigned(1)
    maxU: NN32 = BITNOT zeroU
    bigU: NN32 = oneU LSHIFT 16

    assert(shown(maxU DOTPLUS oneU), "0 : NN32", "opr-overview.tex:205-209: NN32 MAX DOTPLUS 1 wraps")
    assert(shown(zeroU DOTMINUS oneU), "4294967295 : NN32", "opr-overview.tex:205-209: NN32 0 DOTMINUS 1 wraps")
    assert(shown(DOTMINUS oneU), "4294967295 : NN32", "opr-overview.tex:205-209: NN32 DOTMINUS 1 wraps")
    assert(shown(DOTMINUS zeroU), "0 : NN32", "opr-overview.tex:205-209: NN32 DOTMINUS 0")
    assert(shown(maxU DOTTIMES maxU), "1 : NN32", "opr-overview.tex:172-176: NN32 MAX DOTTIMES MAX wraps")
    assert(shown(bigU DOTTIMES bigU), "0 : NN32", "opr-overview.tex:172-176: NN32 2^16 DOTTIMES 2^16 wraps")

    zeroUL: NN64 = widen(unsigned(0))
    oneUL: NN64 = widen(unsigned(1))
    maxUL: NN64 = BITNOT zeroUL
    bigUL: NN64 = oneUL LSHIFT 32

    assert(shown(maxUL DOTPLUS oneUL), "0 : NN64", "opr-overview.tex:205-209: NN64 MAX DOTPLUS 1 wraps")
    assert(shown(zeroUL DOTMINUS oneUL), "18446744073709551615 : NN64", "opr-overview.tex:205-209: NN64 0 DOTMINUS 1 wraps")
    assert(shown(DOTMINUS oneUL), "18446744073709551615 : NN64", "opr-overview.tex:205-209: NN64 DOTMINUS 1 wraps")
    assert(shown(DOTMINUS zeroUL), "0 : NN64", "opr-overview.tex:205-209: NN64 DOTMINUS 0")
    assert(shown(maxUL DOTTIMES maxUL), "1 : NN64", "opr-overview.tex:172-176: NN64 MAX DOTTIMES MAX wraps")
    assert(shown(bigUL DOTTIMES bigUL), "0 : NN64", "opr-overview.tex:172-176: NN64 2^32 DOTTIMES 2^32 wraps")

    oneZ: ZZ = big(oneL)
    minZ: ZZ = big(minL)
    maxZ: ZZ = big(maxL)

    assert(shown(maxZ DOTPLUS oneZ), "9223372036854775808 : ZZ", "opr-overview.tex:205-209, basic-integers.tex:369-370: ZZ DOTPLUS does not wrap")
    assert(shown(maxZ DOTPLUS oneZ), shown(maxZ + oneZ), "opr-overview.tex:205-209, basic-integers.tex:369-370: ZZ DOTPLUS is +")
    assert(shown(minZ DOTMINUS oneZ), "-9223372036854775809 : ZZ", "opr-overview.tex:205-209, basic-integers.tex:393-394: ZZ DOTMINUS does not wrap")
    assert(shown(minZ DOTMINUS oneZ), shown(minZ - oneZ), "opr-overview.tex:205-209, basic-integers.tex:393-394: ZZ DOTMINUS is -")
    assert(shown(DOTMINUS minZ), "9223372036854775808 : ZZ", "opr-overview.tex:205-209, basic-integers.tex:380-381: ZZ DOTMINUS MIN does not wrap")
    assert(shown(DOTMINUS minZ), shown(-minZ), "opr-overview.tex:205-209, basic-integers.tex:380-381: ZZ unary DOTMINUS is -")
    assert(shown(maxZ DOTTIMES maxZ), "85070591730234615847396907784232501249 : ZZ", "opr-overview.tex:172-176, basic-integers.tex:409: ZZ DOTTIMES does not wrap")
    assert(shown(maxZ DOTTIMES maxZ), shown(maxZ maxZ), "opr-overview.tex:172-176, basic-integers.tex:409: ZZ DOTTIMES is multiplication")

    println "PASS"
  end

end

== explorations/coordinator/FACTS.md, ## Execution model

FACTS.md:26
- **Under `walk`, a native can raise a Fortress exception that a Fortress `catch` sees** (rung I, `explorations/compile-ladder/rung-int-semantics-walk/REPORT.md`, section 4.1): `throw new FortressError((FObject) Driver.getFortressLibrary().getRootValue(name))` from inside a `builtinPrimitive` method reaches `Evaluator.forTry` unchanged (`MethodClosure.java:85-86` has no `catch`) and matches `catch e IntegerOverflow`; `Int.overflow()` (`ProjectFortress/src/com/sun/fortress/interpreter/glue/prim/Int.java:256-259`) is the helper and `WellKnownNames.integerOverflowException` the name. Measured by the 25 `overflows(...)` assertions of `ProjectFortress/tests/IntSemanticsRungI.fss`, whose helper catches nothing but `IntegerOverflow`. Before this rung no native raised one; the interpreter's mapping of every other Java exception is unchanged (`FunctionClosure.java:188-196`), so row 336's division by zero and row 347's `Int.rc` still end the run.

== explorations/coordinator/FACTS.md, ## Landed semantics

FACTS.md:95
- The compiled path's integer rules: `LSHIFT`/`RSHIFT` on `ZZ32` and `ZZ64` give `0` or the replicated sign for a count at or beyond the width and shift the other way by its magnitude for a negative count (`ProjectFortress/src/com/sun/fortress/nativeHelpers/simpleIntArith.java:353-362`, `simpleLongArith.java:322-331`; bodies `ProjectFortress/LibraryBuiltin/CompilerBuiltin.fss:647-648`, `:736-737`), while `<<`, `>>` and `<<<` keep their old meanings; on `ZZ32` and `ZZ64` only the minimum overflows or saturates, so `|0|`, `-0`, `0 DIV -1`, `DOTMINUS 0` and every zero factor on `ZZ64` answer `0`, `REM`, `MOD`, `GCD` and `LCM` do not throw on a zero quotient, and the long multiply, now `Math.multiplyExact`, answers a product equal to the minimum; `ZZ64.narrow` and `NN64.narrow` keep the low 32 bits (`CompilerBuiltin.fss:659`, `:879`), so `NN64` has no checked narrowing to `NN32` on this path, while the getter `asZZ32` still throws; the `ZZ`'s `<<<` refuses an unrepresentable left shift with a catchable `IntegerOverflow` before the JVM allocates it (`ProjectFortress/src/com/sun/fortress/nativeHelpers/simpleArbitraryPrecisionArith.java:93-102`, row 386). Gated by `ProjectFortress/compiler_tests/IntSemanticsRungB.fss` and `ProjectFortress/library_tests/IntConversionsRungW.fss:43-45`, `:63-64`; row 379's `walk` half is an expected failure, `ProjectFortress/tests/XXXFixedWidthOverflowRungB.fss` (`ce0c7f453`, `c9faa7df4`; `compile-ladder/rung-int-semantics-compiled/REPORT.md`).

